#include<cstdio>



using namespace std;



int n,s;

int memo[1024][1000];



int search(int stat,int sum,int dep){

	if(dep==n)	return memo[stat][sum]=(s==sum);

	if(~memo[stat][sum])	return memo[stat][sum];

//	if(sum>s)	return 0;



	int cnt=0;

	for(int i=0;i<10;i++){

		if((stat&(1<<i))==0){

			stat|=1<<i;

			cnt+=search(stat,sum+i*(n-dep),dep+1);

			stat&=~(1<<i);

		}

	}

	return memo[stat][sum]=cnt;

}



int main(){

	for(;~scanf("%d%d",&n,&s);){

		for(int i=0;i<1024;i++)for(int j=0;j<1000;j++)	memo[i][j]=-1;

		if(n>10 || s>=1000){

			puts("0");

			continue;

		}

		printf("%d
",search(0,0,0));

	}

	return 0;

}

#include<cstdio>

#include<iostream>



#define INF 2100000000



using namespace std;



int minix(int a,int b,int c){

	if(b>=a && c>=a){

		return a;

	}

	if(a>=b && c>=b){

		return b;

	}

	if(b>=c && a>=c){

		return c;

	}

}



int main(){

	int n;

	int masu[1002][1002];

	int ura[1002][1002];

	char str[1002];

	while(1){

		for(int i=0;i<=1001;i++){

			for(int j=0;j<=1001;j++){

				masu[i][j]=0;

			}

		}

		scanf("%d",&n);

		if(n==0){

			break;

		}

		for(int i=1;i<=n;i++){

			scanf("%s",str);

			for(int j=1;j<=n;j++){

				if(str[j-1]=='.'){

					ura[i][j]=0;

				}else{

					ura[i][j]=1;

				}

			}

		}



		int maxi=0;

		for(int i=1;i<=n;i++){

			for(int j=1;j<=n;j++){

				if(ura[i][j]==0){

					masu[i][j]=minix(masu[i-1][j],masu[i][j-1],masu[i-1][j-1])+1;

					maxi=max(masu[i][j],maxi);

				}

			}

		}



		printf("%d
",maxi);

	}

}

