int dp[1001][1001];

int latte(int i,int j,int k){

    return dp[i+k][j+k]-dp[i+k][j-1]-dp[i-1][j+k]+dp[i-1][j-1];

}

int main(){

    int n;

    while(cin>>n,n){

        fill(dp[0],dp[0]+1001*1001,0);

        for(int i=0;i<n;i++){

            string str;

            cin>>str;

            for(int j=0;j<n;j++){

                dp[i+1][j+1]=dp[i][j+1]+dp[i+1][j]-dp[i][j];

                if(str[j]=='*')dp[i+1][j+1]++;

            }

        }

        int Max=0;

        for(int i=1;i<=n;i++){

            for(int j=1;j<=n;j++){

                if(latte(i,j,0))continue;

                int lb=0,ub=min(n-i,n-j)+1;

                while(ub-lb>1){

                    int k=(ub+lb)/2;

                    //if(i+k>n||j+k>n)ub=k;

                    if(latte(i,j,k))ub=k;

                    else lb=k;

                }

                Max=max(Max,lb+1);

            }

        }

        cout<<Max<<endl;

    }

}

#include <iostream>

#include <string>

using namespace std;

typedef struct{

	string id;

	long long sales;

} staff;



int main(void)

{

	long long n;

	while(cin>>n){

		if(!n) break;

		staff staff1[4001];

		int pt = 0;

		for(int i=0; i< n; i++){

			string id;

			cin >> id;

			long long price;

			int bnum;

			cin >> price >> bnum;

			int m=-1;

			for(int j=0;j < i; j++){

				if(id==staff1[j].id){

					pt++;

					m=j;

					break;

				}

			}

			if(m==-1){

				staff1[i-pt].id = id;

				staff1[i-pt].sales = price * bnum;

			}else{

				staff1[m].sales += price * bnum;

			}

		}

		int count = 0;

		for(int i=0; i < n-pt; i++){

			if(staff1[i].sales >= 1000000){

				count++;

				cout << staff1[i].id << endl;

			}

		}

		if(!count) cout << "NA" << endl;

	}



	return 0;

}

