VI memo;



int solve( int n )

{

	if ( n == 0 )

	{

		return 1;

	}

	else if ( n < 0 )

	{

		return 0;

	}



	if ( memo[n] != -1 )

	{

		return memo[n];

	}



	return solve( n - 1 ) + solve( n - 2 ) + solve( n - 3 );

}



int main()

{

	while ( true )

	{

		int n;

		cin >> n;



		if ( n == 0 )

		{

			break;

		}



		memo.resize( n + 1 );

		fill( ALL( memo ), -1 );



		cout << solve( n ) / 3650 + 1 << endl;

	}



	return 0;

}

