    for (int i=0; i<n; i++) {

      u[i] = false;

    }

    maxg = -DBL_MAX;

    dfs(0, 0, 0, 0.);

    for (int i=n-1; i>=0; i--) {

      printf("%s
", f[b[i]]);

    }

  }

  return 0;

}

